const axios = require('axios'); // Make sure to install this package using npm or yarn before running the code

async function postMessageToSlackChannel(text, channel) {
  try {
    const options = {
      method: 'post',
      url: `https://slack.com/api/chat.postMessage`,
      headers: { 'Content-Type': 'application/json' },
      data: {
        channel: channel,
        text: text,
      },
