```javascript
function sortJsonByKeys(jsonObject) {
  // First, convert the JSON object into an array of key-value pairs using Object.entries()
  const entries = Object.entries(jsonObject);

  // Next, use the Array.prototype.sort() method to sort the array based on the keys
  entries.sort((a, b) => {
