    }

    if (!isdigit(b + '.1'[0]) || !isdigit(b + '.1'[1])) {
        throw invalid_argument("Invalid input: Second number must be a valid integer.");
    }

    if (n <= 0) {
        throw invalid_argument("Invalid input: Number of sequence elements must be positive.");
    }

    try {
        cout << a << ", ";
        if (n > 1) {
            generateFibonacciSequence(fibonacci(a), fibonacci(a + 1), n - 1);
        }
