 To retrieve the username from a JSON Web Token (JWT) in an ASP.NET C# WebApi, you'll first need to verify and decode the token. Here's a step-by-step guide on how to achieve that:

1. Install the required NuGet packages: `Microsoft.IdentityModel.Tokens` and `System.IdentityModel.Tokens.Jwt`.

```sh
Install-Package Microsoft.IdentityModel.Tokens
Install-Package System.IdentityModel.Tokens.Jwt
```

2. Create a method to validate and decode the JWT:

```csharp
using System;
using System.IdentityModel.Tokens.Jwt;
using Microsoft.AspNetCore.Authorization;
using Microsoft.Extensions.Primitives;
using Microsoft.IdentityModel.Tokens;

public static string GetUsernameFromJwtToken(string jwtToken)
{
    try
    {
        // Handler for JWT tokens
        var handler = new JwtSecurityTokenHandler();

        // Validate and parse the JWT
        JwtSecurityToken securityToken;
        securityToken = handler.ReadJwtToken(jwtToken);

        // Retrieve the username from the claims
        var identityClaims = securityToken.Claims;
        string username = null;

        foreach (var claim in identityClaims)
        {
            if (claim.Type == ClaimTypes.Name || claim.Type == "sub")
            {
                username = claim.Value;
                break;
            }
        }

        return username;
    }
    catch (Exception ex)
    {
        Console.WriteLine("Error retrieving username from JWT token: {0}", ex.Message);
        throw;
    }
}
```

