public class Visualizer : MonoBehaviour
{
    public AudioClip audioClip; // Assign your audio clip here
    public GameObject visualizerPrefab; // Assign your visualizer prefab here
    public float visualizerSpawnRate = 0.05f; // Spawn rate of visualizers per second

    private AudioSource _audioSource;
    private List<GameObject> _visualizers = new List<GameObject>();

    private void Start()
    {
        _audioSource = GetComponent<AudioSource>();
        _audioSource.clip = audioClip;
        _audioSource.Play();

        InvokeRepeating("SpawnVisualizer", 0f, visualizerSpawnRate);
    }

    private void SpawnVisualizer()
    {
        if (_audioSource.isPlaying)
        {
            var visualizer = Instantiate(visualizerPrefab, transform);
            visualizer.transform.localPosition = Vector3.zero;
            _visualizers.Add(visualizer);
        }
    }

    private void Update()
    {
        if (_visualizers.Count > 0)
        {
            float currentTime = _audioSource.time / _audioSource.clip.length;
            foreach (var visualizer in _visualizers)
            {
                VisualizerBar bar = visualizer.GetComponent<VisualizerBar>();
                if (bar != null)
                    bar.SetValue(currentTime);
            }
        }
    }
}
```

