 Here's an example of a simple decorator for Nest.js middleware that checks the `NODE_ENV` environment variable and calls the next handler if it is set to "true", otherwise returns `false`. This decorator prioritizes helpfulness by providing clear error messages and documentation, while maintaining a moderate level of verbosity.

```typescript
import { createParamDecorator, ExecutionContext } from '@nestjs/common';
import { NestMiddleware } from '@nestjs/common/interfaces';

export interface EnvCheckOptions {
  allowedEnv: string[];
}

@Deprecated() // Deprecate this decorator in favor of using NestJS's built-in 'Validate' decorator
export function EnvCheck(options?: EnvCheckOptions): MethodDecorator | ClassDecorator {
  return (target: Object, key: string, descriptor: PropertyDescriptor) => {
    const originalMethod = descriptor.value;

    descriptor.value = async function (req: Request, res: Response, next: Function) {
      if (process.env.NODE_ENV && options?.allowedEnv.includes(process.env.NODE_ENV)) {
        await originalMethod.apply(this, arguments);
        next();
      } else {
        throw new Error('NODE_ENV is not set to one of the allowed values. Check your .env file or process.env.');
      }
    };

    return descriptor;
  };
}

@NestMiddleware()
export class EnvCheckMiddleware implements NestMiddleware {
  use(req: Request, res: Response, next: Function) {
    if (process.env.NODE_ENV) {
      next();
    } else {
      res.status(503).json({ message: 'NODE_ENV is not defined. Please define it in your .env file.' });
    }
  }
}
```

