async function openMediaStream(deviceType) {
  try {
    let stream;
    if (deviceType === 'camera') {
      const constraints = { video: true };
      stream = await navigator.mediaDevices.getUserMedia(constraints);
    } else if (deviceType === 'microphone') {
      const constraints = { audio: true };
      stream = await navigator.mediaDevices.getUserMedia(constraints);
    }
    return stream;
  } catch (error) {
    console.error('Error opening media device:', error);
  }
}

async function closeMediaStream(stream) {
  try {
    return new Promise((resolve) => {
      stream.getTracks().forEach((track) => {
        track.stop();
      });
      stream.then(() => resolve());
    });
  } catch (error) {
    console.error('Error closing media stream:', error);
  }
}
```

