 To identify if a given sentence in Go contains a double negative, you can follow these steps:

1. Define a slice of specific negative words that can be part of a double negative construction.
2. Tokenize the sentence into words.
3. Iterate through each token in the sentence.
4. Check if the current token is in the slice of negative words or the phrase "not" followed by a negative word.
5. If a negative word or the phrase "not" followed by a negative word is found, check the next token.
6. If the next token is the word "not," then there is a double negative.
7. If no double negative is found, continue iterating through the tokens.
8. If all tokens have been checked and no double negative was found, print a message indicating that the sentence does not contain a double negative.

Here's an example implementation of the above steps in Go:

```go
package main

import (
	"fmt"
	"strings"
)

func main() {
	negativeWords := []string{"ain't", "isn't", "aren't", "doesn't", "don't", "haven't", "hasn't", "hadn't", "won't", "wouldn't", "can't", "couldn't", "shall not", "shouldn't", "mustn't"}
	sentence := "He isn't not worried about the coronavirus situation"

	words := strings.Split(sentence, " ")
	lastNegative := false
	for i, word := range words {
		if containsNegation(word) && lastNegative {
			fmt.Println("Double negative detected")
			return
		}
		lastNegative = containsNegation(word)
	}

	if !lastNegative {
		fmt.Println("No double negative found")
	}
}

func containsNegation(word string) bool {
	for _, negWord := range negativeWords {
		if strings.HasPrefix(word, negWord) || word == "not" {
			return true
		}
	}
	return false
}

