 I'd be happy to help you write a PowerShell script for recursively checking folders to see if their Access Control Lists (ACLs) contain Security Identifiers (SIDs) that exist only in the SID history of any user or group in the Active Directory domain. Here's an example script:

```powershell
# Set the starting point for the script, change it as needed
$startingFolderPath = "C:\YourStartingFolderPath"

# Function to check if a SID exists in the SID history of a user or group
function Get-ADObjectWithSidInSidHistory ($sid) {
    $filter = "(objectClass -eq 'user') -or (objectClass -eq 'group')"
    $searcher = New-Object -ComObject "ADSISEDIT.ADSExtendedSearcher"
    $searcher.SearchRoot = "LDAP://DC=yourdomain,DC=com"
    $searcher.Filter = "$filter"
    $results = @()

    Do {
        $result = $searcher.FindNext()
        if ($result -ne $null) {
            $obj = New-Object ADSIObject $result.pspath
            $obj | ForEach-Object {
                if ($_.PropertyName -eq 'SID') {
                    $sidObj = New-Object System.Security.Principal.SecurityIdentifier($_.Value)
                    if ($sidObj.Translate([System.Security.Principal.NTAccount]).Value -eq $null) { # Check if it is a SID history
                        $sidArray = $sidObj.Value.Split('-')
                        if ($sidArray[0] -eq $sid) {
                            $results += $obj
                            break
                        }
                    }
                }
            }
        } else {
            break
        }
    } while ($true)

    return $results
}

# Function to get the effective access for a folder
function Get-EffectiveAccess ($folderPath, $identityReference) {
    $access = Get-Acl -Path $folderPath | Select-Object -ExpandProperty Access | Where-Object {$_.IdentityReference -eq $identityReference}
